 private void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 private void command(Player p,String... args){check(mando.getCommand("c").execute(p,"c",args),"Actual clan command executes "+String.join(" ",args));}
 private void move(Player p,World w,int x,int z){check(p.teleport(new Location(w,x*16+.5,280,z*16+.5)),"Move to test chunk "+x+","+z);p.setGravity(false);acknowledge(p);}
 private void acknowledge(Player player){try{
  Object handle=handles.get(player.getUniqueId());Object listener=handle.getClass().getField("connection").get(handle);Class<?> type=listener.getClass();
  var position=type.getDeclaredField("awaitingPositionFromClient");position.setAccessible(true);
  if(position.get(listener)!=null){var id=type.getDeclaredField("awaitingTeleport");id.setAccessible(true);var packet=Class.forName("net.minecraft.network.protocol.game.ServerboundAcceptTeleportationPacket");type.getMethod("handleAcceptTeleportPacket",packet).invoke(listener,packet.getConstructor(int.class).newInstance(id.getInt(listener)));}
  var loaded=Class.forName("net.minecraft.network.protocol.game.ServerboundPlayerLoadedPacket");type.getMethod("handleAcceptPlayerLoad",loaded).invoke(listener,loaded.getConstructor().newInstance());
 }catch(Exception e){throw new RuntimeException("Native fixture load acknowledgement failed",e);}}
