  var owned=leader.getInventory();owned.clear();for(int i=0;i<36;i++)owned.setItem(i,new ItemStack(Material.DIAMOND,64));owned.setHelmet(new ItemStack(Material.IRON_HELMET));owned.setItemInOffHand(new ItemStack(Material.EMERALD,9));var before=Arrays.stream(owned.getContents()).map(i->i==null?null:i.clone()).toArray(ItemStack[]::new);command(leader);var view=leader.getOpenInventory();check(view.getTopInventory().getSize()==54&&view.getTopInventory().getHolder().getClass().getName().contains("ClanMenu"),"Noargs c opens native clan menu");
  var heads=Arrays.stream(view.getTopInventory().getContents()).filter(i->i!=null&&i.getType()==Material.PLAYER_HEAD).toList();check(heads.size()==clan.members.size(),"Actual head for every clan member");for(var head:heads){var meta=(SkullMeta)head.getItemMeta();check(meta.getOwnerProfile()!=null&&clan.members.contains(meta.getOwnerProfile().getUniqueId()),"Roster head has real member UUID");}
