  var number=new InventoryClickEvent(view,InventoryType.SlotType.CONTAINER,27,ClickType.NUMBER_KEY,InventoryAction.HOTBAR_SWAP,2);Bukkit.getPluginManager().callEvent(number);check(number.isCancelled(),"Menu number key denied");var bottom=new InventoryClickEvent(view,InventoryType.SlotType.CONTAINER,54,ClickType.SHIFT_LEFT,InventoryAction.MOVE_TO_OTHER_INVENTORY);Bukkit.getPluginManager().callEvent(bottom);check(bottom.isCancelled(),"Bottom inventory shift denied");var menuDrag=new InventoryDragEvent(view,new ItemStack(Material.STONE),new ItemStack(Material.STONE),false,Map.of(27,new ItemStack(Material.STONE)));Bukkit.getPluginManager().callEvent(menuDrag);check(menuDrag.isCancelled(),"Menu drag denied");slotsEqual(before,leader);command(leader,"help");leader.closeInventory();
  leader.setItemOnCursor(new ItemStack(Material.EMERALD,3));command(leader);check(!(leader.getOpenInventory().getTopInventory().getHolder().getClass().getName().contains("ClanMenu"))&&leader.getItemOnCursor().getAmount()==3,"Menu defers cursor safely");leader.setItemOnCursor(null);if(leader.getOpenInventory().getTopInventory() instanceof CraftingInventory crafting){crafting.setMatrix(new ItemStack[]{new ItemStack(Material.DIAMOND),null,null,null});command(leader);check(crafting.getMatrix()[0].getType()==Material.DIAMOND,"Crafting ingredient survives deferred menu");crafting.setMatrix(new ItemStack[4]);}slotsEqual(before,leader);
